    @Test void completeMultiSourceNativeGoldAndStandaloneEquivalence()throws Exception {
        multi=true;silver();var receipts=jdbc.queryForList("SELECT source_id,encode(receipt_bytes,'hex') AS receipt,journal_sha256 FROM ddip_management.rss_deliveries ORDER BY source_id");var nativeBefore=snapshot(roots.get(SILVER_BINDING));
        // Queue while live, before ownerless read-only Spark inspections can age the heartbeat.
        owner=workers.heartbeat(guard,owner);var queued=content();((tools.jackson.databind.node.ObjectNode)queued.get("fetchSources").get(0)).put("revision",2);queued.withArray("retainedSilverArtifactIds").add(jdbc.queryForList("SELECT artifact_id FROM ddip_management.stage_artifacts WHERE stage='SILVER' ORDER BY item_ordinal").getFirst().get("artifact_id").toString());submit(queued,"unrelated");assertThatThrownBy(()->workers.claim(guard,owner.worker(),UUID.randomUUID())).hasMessage("WORKER_NOT_READY");
        prepare();var preparation=SourceJson.parse(prepared.bytes(),16*1024*1024).get("prepared");assertThat(preparation.get("manifest").get("inputs").size()).isEqualTo(2);
        assertThat(preparation.get("counts").get("accepted").intValue()).isEqualTo(4);assertThat(preparation.get("counts").get("rejected").intValue()).isEqualTo(2);
        sources.execute(SourceCommands.command(SourceCommands.Action.REVISE,CONTENT,"demo-feed",revise("later source",rss().put("feedEndpointId",ENDPOINT2)),"later-source","\"1\""),"test");
        var result=publish();var evidence=SourceJson.parse(result.evidence(),16*1024*1024);assertThat(evidence.get("verification").get("completion").get("output_counts")).isEqualTo(SourceJson.object().put("gold_articles",2).put("gold_source_daily",2));
        var before=snapshot(gold());assertThat(inspectGold()).isEqualTo(result.artifact());assertThat(snapshot(gold())).isEqualTo(before);assertThat(snapshot(roots.get(SILVER_BINDING))).isEqualTo(nativeBefore);
        assertThat(jdbc.queryForList("SELECT source_id,encode(receipt_bytes,'hex') AS receipt,journal_sha256 FROM ddip_management.rss_deliveries ORDER BY source_id")).isEqualTo(receipts);
        String address=jdbc.queryForObject("SELECT command_address FROM ddip_management.stage_invocations WHERE stage='PUBLISH_GOLD'",String.class);Path standalone=Files.createTempDirectory(temp,"standalone-");
        try(var measured=timing.phase("standalone")){var p=new ProcessBuilder(System.getenv("DDIP_TEST_PYTHON"),"-I","-B",Path.of("../../processing/tests/managed_gold_fixture.py").toRealPath().toString(),guard.binding().root().resolve(address).toString(),standalone.toString()).redirectError(ProcessBuilder.Redirect.DISCARD).start();assertThat(p.waitFor(180,java.util.concurrent.TimeUnit.SECONDS)).isTrue();assertThat(p.exitValue()).isZero();assertThat(p.inputReader().readLine()).isEqualTo("EQUIVALENT");}assertThat(snapshot(gold())).isEqualTo(before);
        assertThat(count("artifacts")).isEqualTo(8);assertThat(count("stage_invocations")).isEqualTo(8);assertThat(count("artifact_dependencies")).isEqualTo(2);assertThat(requests.get()).isEqualTo(2);assertThat(proxy.puts.get()).isEqualTo(4);
        assertThat(jdbc.queryForObject("SELECT state FROM ddip_management.runs WHERE run_id=?",String.class,owner.runId())).isEqualTo("RUNNING");assertThat(jdbc.queryForObject("SELECT active_attempt_id FROM ddip_management.coordinator",UUID.class)).isEqualTo(owner.attemptId());assertThat(jdbc.queryForObject("SELECT count(*) FROM ddip_management.stage_invocations WHERE stage IN ('PUBLISH_CONTENT','VERIFY_RESULT')",Integer.class)).isZero();
        System.out.println("D4_NATIVE_EVIDENCE "+preparation.get("inputSetFingerprint")+" "+evidence.get("verification").get("completion").get("output_counts")+" completeSha="+SourceJson.sha(Files.readAllBytes(gold().resolve("complete.json"))));
        assertThatThrownBy(this::publish).isInstanceOf(RuntimeException.class);
    }
