    @ParameterizedTest @ValueSource(strings={"missing","changed"}) void selectedSilverCannotChange(String mode)throws Exception {silver();Path file;try(var paths=Files.walk(roots.get(SILVER_BINDING))){file=paths.filter(p->p.toString().endsWith(".parquet")).findFirst().orElseThrow();}if(mode.equals("missing"))Files.delete(file);else Files.write(file,new byte[]{1,2});assertThatThrownBy(this::prepare).isInstanceOf(RuntimeException.class);occupied();}
    @ParameterizedTest @ValueSource(strings={"missing","changed"}) void preparedSilverCannotChangeBeforePublication(String mode)throws Exception {silver();prepare();Path file;try(var paths=Files.walk(roots.get(SILVER_BINDING))){file=paths.filter(p->p.toString().endsWith(".parquet")).findFirst().orElseThrow();}if(mode.equals("missing"))Files.delete(file);else Files.write(file,new byte[]{1,2});assertThatThrownBy(this::publish).isInstanceOf(RuntimeException.class);occupied();assertThat(Files.exists(gold())).isFalse();}
    @Test void preparedFingerprintCannotBeSubstituted()throws Exception {silver();prepare();String addr=jdbc.queryForObject("SELECT command_address FROM ddip_management.stage_invocations WHERE stage='PREPARE_GOLD'",String.class);Path evidence=guard.binding().root().resolve(addr).resolveSibling("evidence.json");var value=(tools.jackson.databind.node.ObjectNode)SourceJson.parse(Files.readAllBytes(evidence),16*1024*1024);((tools.jackson.databind.node.ObjectNode)value.get("prepared")).put("inputSetFingerprint","0".repeat(64));Files.write(evidence,SourceJson.canonical(value));assertThatThrownBy(this::publish).hasMessage("INPUT_CHANGED");occupied();assertThat(Files.exists(gold())).isFalse();}
    @Test void incompleteGoldIsNeverResumedOrDeleted()throws Exception {silver();prepare();Files.createDirectories(gold());Files.writeString(gold().resolve("partial"),"partial");var before=snapshot(gold());assertThatThrownBy(this::publish).isInstanceOf(RuntimeException.class);assertThat(snapshot(gold())).isEqualTo(before);occupied();assertThatThrownBy(this::publish).isInstanceOf(RuntimeException.class);}
    @ParameterizedTest @ValueSource(strings={"marker","parquet"}) void independentVerifierRejectsCorruptOutput(String mode)throws Exception {silver();prepare();var once=new java.util.concurrent.atomic.AtomicBoolean();assertThatThrownBy(()->publish((phase,point,o)->{if(point.equals("AFTER_CHILD") && once.compareAndSet(false,true))try{if(mode.equals("marker"))Files.writeString(gold().resolve("complete.json"),"{}");else try(var files=Files.walk(gold().resolve("gold_articles"))){Files.write(files.filter(p->p.toString().endsWith(".parquet")).findFirst().orElseThrow(),new byte[]{1,2});}}catch(Exception ex){throw new IllegalStateException(ex);}})).isInstanceOf(RuntimeException.class);occupied();var corrupt=snapshot(gold());assertThatThrownBy(this::publish).isInstanceOf(RuntimeException.class);assertThat(snapshot(gold())).isEqualTo(corrupt);}
    @ParameterizedTest @ValueSource(strings={"stale","guard","outage","interrupt","uncertain"}) void childFailureRetainsOwnership(String mode)throws Exception {silver();prepare();var once=new java.util.concurrent.atomic.AtomicBoolean();assertThatThrownBy(()->publish((phase,point,o)->{if(point.equals("CHILD_STARTED") && once.compareAndSet(false,true))switch(mode){case "stale"->jdbc.update("UPDATE ddip_management.coordinator SET row_version=row_version+1");case "guard"->guard.close();case "outage"->outage(true);case "interrupt"->Thread.currentThread().interrupt();case "uncertain"->throw new PreflightFailure(PreflightFailure.Code.TERMINATION_UNCONFIRMED,false);}})).isInstanceOf(RuntimeException.class);Thread.interrupted();if(mode.equals("outage"))outage(false);occupied();assertThatThrownBy(this::publish).isInstanceOf(RuntimeException.class);}
    @Test void launchFailureIsKnownCleanButStillOccupied()throws Exception {
        silver();prepare();
        var authorized=new java.util.concurrent.atomic.AtomicInteger();
        var started=new java.util.concurrent.atomic.AtomicInteger();
        assertThatThrownBy(()->publish((phase,point,o)->{
            if(point.equals("CHILD_STARTED"))started.incrementAndGet();
            // Existing supervisor beforeStart callback, after committed one-use authorization.
            // No dependency on the installed Python's venv layout or executable mutation.
            if(point.equals("AUTHORIZED")){authorized.incrementAndGet();throw new PreflightFailure(PreflightFailure.Code.PROCESS_START_FAILED,true);}
        })).hasMessage("PROCESS_START_FAILED");
        occupied();assertThat(Files.exists(gold())).isFalse();
        assertThat(authorized.get()).isEqualTo(1);assertThat(started.get()).isZero();
        assertThat(jdbc.queryForObject("SELECT state FROM ddip_management.stage_invocations WHERE stage='PUBLISH_GOLD'",String.class)).isEqualTo("FAILED");
        assertThat(jdbc.queryForObject("SELECT child_pid IS NULL AND command_sha256 IS NOT NULL FROM ddip_management.stage_invocations WHERE stage='PUBLISH_GOLD'",Boolean.class)).isTrue();
        assertThatThrownBy(()->publish((phase,point,o)->{if(point.equals("AUTHORIZED"))authorized.incrementAndGet();if(point.equals("CHILD_STARTED"))started.incrementAndGet();})).isInstanceOf(RuntimeException.class);
        assertThat(authorized.get()).isEqualTo(1);assertThat(started.get()).isZero();
        assertThat(jdbc.queryForObject("SELECT count(*) FROM ddip_management.stage_invocations WHERE stage='PUBLISH_GOLD'",Integer.class)).isEqualTo(1);
    }

    @ParameterizedTest @ValueSource(strings={"INTENT","AUTHORIZED","AFTER_CHILD","VERIFIED"}) void ambiguousInvocationCannotStartSecondPublisher(String boundary)throws Exception {silver();prepare();var latest=new java.util.concurrent.atomic.AtomicReference<WorkerRepository.Owner>();assertThatThrownBy(()->publish((phase,point,o)->{latest.set(o);if(point.equals(boundary))throw new AssertionError("crash");})).isInstanceOf(AssertionError.class);prepared=RssGoldTestSupport.withOwner(prepared,latest.get());owner=latest.get();workers=WorkerTestSupport.enabled(jdbc,tx,INSTALL);var before=snapshot(roots.get("content-GOLD"));assertThatThrownBy(this::publish).isInstanceOf(RuntimeException.class);assertThat(snapshot(roots.get("content-GOLD"))).isEqualTo(before);occupied();assertThat(jdbc.queryForObject("SELECT count(*) FROM ddip_management.stage_invocations WHERE stage='PUBLISH_GOLD'",Integer.class)).isEqualTo(1);}
    @ParameterizedTest @ValueSource(strings={"INSERT INTO ddip_management.stage_invocations","SET command_address="}) void lostLaunchAcknowledgmentNeverPublishes(String sql)throws Exception {silver();prepare();installLostCommit(sql);loseAck.set(true);assertThatThrownBy(this::publish).hasMessage("MANAGEMENT_UNAVAILABLE");occupied();assertThat(Files.exists(gold())).isFalse();assertThatThrownBy(this::publish).hasMessage("OWNERSHIP_LOST");}
    @Test void lostVerifiedAcknowledgmentConfirmsWithoutAnotherRegistration()throws Exception {silver();prepare();installLostCommit("SET state='VERIFIED',result_address=");assertThatThrownBy(()->publish((phase,point,o)->{if(point.equals("BEFORE_CHECKPOINT"))loseAck.set(true);})).hasMessage("MANAGEMENT_UNAVAILABLE");var before=snapshot(gold());assertThat(inspectGold()).isNotNull();assertThat(snapshot(gold())).isEqualTo(before);assertThat(jdbc.queryForObject("SELECT count(*) FROM ddip_management.artifacts WHERE kind='GOLD'",Integer.class)).isEqualTo(1);assertThatThrownBy(this::publish).hasMessage("OWNERSHIP_LOST");}
    @Test void lostPreparationAcknowledgmentCannotAuthorizeGold()throws Exception {silver();installLostCommit("SET state='VERIFIED',result_address=");assertThatThrownBy(()->prepare((phase,point,o)->{if(point.equals("BEFORE_CHECKPOINT"))loseAck.set(true);})).hasMessage("MANAGEMENT_UNAVAILABLE");occupied();assertThat(jdbc.queryForObject("SELECT count(*) FROM ddip_management.stage_invocations WHERE stage='PUBLISH_GOLD'",Integer.class)).isZero();assertThatThrownBy(this::prepare).hasMessage("OWNERSHIP_LOST");}
    @ParameterizedTest @ValueSource(strings={"artifacts","audit_events"}) void artifactAndAuditRegistrationAreAtomic(String table)throws Exception {silver();prepare();assertThatThrownBy(()->publish((phase,point,o)->{if(point.equals("BEFORE_CHECKPOINT")){jdbc.execute("CREATE FUNCTION ddip_management.d4_fault() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION USING MESSAGE='PRIVATE',ERRCODE='23514'; END $$");jdbc.execute("CREATE TRIGGER d4_fault BEFORE INSERT ON ddip_management."+table+" FOR EACH ROW EXECUTE FUNCTION ddip_management.d4_fault()");}})).hasMessage("STATE_CONFLICT");occupied();assertThat(Files.exists(gold().resolve("complete.json"))).isTrue();}
    @Test void conflictingRegistryIdentityIsNotReused()throws Exception {silver();prepare();assertThatThrownBy(()->publish((phase,point,o)->{if(point.equals("BEFORE_CHECKPOINT"))try{String address=jdbc.queryForObject("SELECT command_address FROM ddip_management.stage_invocations WHERE stage='PUBLISH_GOLD'",String.class);byte[] e=Files.readAllBytes(guard.binding().root().resolve(address).resolveSibling("selection.json"));var a=SourceJson.parse(e,16*1024*1024);UUID candidate=UUID.randomUUID();jdbc.update("INSERT INTO ddip_management.artifacts(artifact_id,kind,product_id,contract_version,processor_revision,native_identity,storage_binding_id,relative_address,evidence_bytes,evidence_sha256,verified_at) VALUES (?,'SILVER','content-intelligence',1,1,?,?,?,?,?,clock_timestamp())",candidate,"0".repeat(64),a.get("storageBindingId").stringValue(),a.get("relativeAddress").stringValue(),e,SourceJson.sha(e));for(int i=0;i<a.get("inputs").size();i++)jdbc.update("INSERT INTO ddip_management.artifact_dependencies VALUES (?,'SILVER',?,?)",candidate,i,UUID.fromString(a.get("inputs").get(i).get("artifactId").stringValue()));}catch(Exception ex){throw new IllegalStateException(ex);}})).hasMessage("RUNTIME_MISMATCH");occupied();assertThat(jdbc.queryForObject("SELECT state FROM ddip_management.stage_invocations WHERE stage='PUBLISH_GOLD'",String.class)).isEqualTo("RUNNING");assertThat(Files.exists(gold().resolve("complete.json"))).isTrue();assertThat(jdbc.queryForObject("SELECT count(*) FROM ddip_management.stage_artifacts WHERE stage='PUBLISH_GOLD'",Integer.class)).isZero();}
    @Test void verifiedGoldSurvivesDatabaseRestart()throws Exception {silver();prepare();var result=publish();var before=snapshot(gold());String signal=System.getProperty("ddip.test.gold-restart-signal");if(signal!=null){Path p=Path.of(signal);Files.writeString(p,"RESTART\n");long end=System.nanoTime()+java.time.Duration.ofSeconds(60).toNanos();while(!Files.exists(Path.of(signal+".done")) && System.nanoTime()<end)Thread.sleep(50);assertThat(Files.exists(Path.of(signal+".done"))).isTrue();}assertThat(inspectGold()).isEqualTo(result.artifact());assertThat(snapshot(gold())).isEqualTo(before);assertThat(jdbc.queryForObject("SELECT active_attempt_id FROM ddip_management.coordinator",UUID.class)).isEqualTo(owner.attemptId());}
